export function DetailList({
  heading = "{{heading}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showNote = {{showNote}},
  labelWidth = {{labelWidth}},
}) {
  const rows = [["Order", "#1042"], ["Customer", "A. Whitfield"], ["Status", "Shipped"]];
  if (showNote) rows.push(["Note", "Left at the front desk"]);
  const inline = layout === "inline";
  const grid = layout === "grid";
  const dlStyle = grid ? { margin: 0, display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px 16px" } : { margin: 0 };
  const rowStyle = inline
    ? { display: "flex", gap: 12, alignItems: "baseline", padding: "8px 0", borderBottom: "1px solid #24143014" }
    : grid
    ? { padding: 0 }
    : { padding: "8px 0", borderBottom: "1px solid #24143014" };
  const dtStyle = { color: accent, fontWeight: 600, fontSize: inline ? 13 : 12, textTransform: inline ? "none" : "uppercase", letterSpacing: ".03em", margin: 0, flex: inline ? `0 0 ${labelWidth}px` : undefined };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 340, width: 340, padding: 18, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <dl style={dlStyle}>
        {rows.map(([label, value]) => (
          <div key={label} style={rowStyle}>
            <dt style={dtStyle}>{label}</dt>
            <dd style={{ margin: inline ? 0 : "2px 0 0" }}>{value}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}
